def purge_expired(sessions, now):
    """Remove every session whose "expires_at" is <= now from the list `sessions`, in place. Return how many were removed."""
    removed = 0
    for session in sessions:
        if session["expires_at"] <= now:
            sessions.remove(session)
            removed += 1
    return removed

