def purge_expired(sessions, now):
    before = len(sessions)
    # Build the list of live sessions and write it back into the same list object (slice assignment),
    # instead of deleting items from the list we are looping over.
    sessions[:] = [session for session in sessions if session["expires_at"] > now]
    return before - len(sessions)
